import type http from "node:http";
import { handleChatStream } from "@mastra/ai-sdk";
import { RequestContext } from "@mastra/core/request-context";
import { toAISdkMessages } from "@mastra/ai-sdk/ui";
import { createUIMessageStreamResponse, type UIMessage } from "ai";
import { canUseAgent } from "./auth/access";
import { approvalResumeMessage, pendingApprovalIds, withoutPendingApprovals } from "./chat-approvals";
import type { SessionUser } from "./auth/session";
import { mastra } from "./mastra";
import { traceRequest } from "./telemetry";
import { USER_ROLE_KEY, WORKSPACE_USER_KEY } from "./mastra/workspace";

const MAX_BODY_BYTES = 1024 * 1024;

export type AgentSummary = { key: string; id: string; name: string; description: string };

/** Without a user, returns every agent; with one, only the agents that user may use. */
export function listAgents(user?: SessionUser): AgentSummary[] {
  return Object.entries(mastra.listAgents())
    .map(([key, agent]) => ({
      key,
      id: agent.id,
      name: agent.name,
      description: agent.getDescription(),
    }))
    .filter((agent) => !user || canUseAgent(user, agent.id));
}

/** Accepts either the Mastra registry key ("cfoAgent") or the agent id ("cfo"). */
function resolveAgentId(keyOrId: string): string | undefined {
  return listAgents().find((agent) => agent.key === keyOrId || agent.id === keyOrId)?.id;
}

/** One persisted chat per user per agent. */
export function chatThreadId(userId: string, agentId: string): string {
  return `${userId}:${agentId}`;
}

/** POST /api/chat/:agentId — streams an AI SDK v7 UI message stream (SSE). */
export async function handleChat(
  agentKeyOrId: string,
  req: http.IncomingMessage,
  res: http.ServerResponse,
  user: SessionUser,
): Promise<void> {
  if (req.method !== "POST") {
    res.writeHead(405, { allow: "POST" }).end();
    return;
  }
  const agentId = resolveAgentId(agentKeyOrId);
  if (!agentId) {
    sendJson(res, 404, { error: `Unknown agent: ${agentKeyOrId}` });
    return;
  }
  if (!canUseAgent(user, agentId)) {
    sendJson(res, 403, { error: "Forbidden" });
    return;
  }

  // Memory already holds the history, so only the newest message is taken from the body: either a
  // new user message, or the assistant message carrying the user's tool-approval decisions.
  let last: UIMessage;
  try {
    const body = JSON.parse(await readBody(req)) as { messages?: unknown; message?: unknown };
    const candidate = (Array.isArray(body?.messages) ? body.messages.at(-1) : body?.message) as UIMessage | undefined;
    if (!candidate || typeof candidate.id !== "string" || !Array.isArray(candidate.parts)) throw new Error("message required");
    if (candidate.role !== "user" && candidate.role !== "assistant") throw new Error("unsupported role");
    last = candidate;
  } catch (error) {
    const tooLarge = error instanceof BodyTooLargeError;
    sendJson(res, tooLarge ? 413 : 400, {
      error: tooLarge ? "Request body too large" : "Expected JSON body whose last message is a user message or a tool approval",
    });
    return;
  }

  let message: UIMessage;
  if (last.role === "user") {
    // Namespace the id by user: storage upserts by message id, so a client-chosen id must not hit another user's rows.
    message = { ...last, id: `${user.id}:${last.id}` };
    await dropPendingApprovals(agentId, user);
  } else {
    // Approval response: only decisions for approvals pending in the caller's own thread are kept.
    // It resumes the suspended run; the message itself is not stored.
    const thread = await ownThread(agentId, user);
    const stored = thread ? (await thread.memory.recall({ ...thread.ids, perPage: false })).messages : [];
    const resume = approvalResumeMessage(last, pendingApprovalIds(stored));
    if (!resume) {
      sendJson(res, 409, { error: "That approval is no longer pending." });
      return;
    }
    message = resume;
  }

  // Stop generation when the browser disconnects.
  const abort = new AbortController();
  res.on("close", () => {
    if (!res.writableFinished) abort.abort();
  });

  // Only the message is taken from the client: other AgentExecutionOptions (instructions,
  // maxSteps, tools, runId...) must not be client-controlled. Memory thread and resource always
  // come from the session, never from the client, and so does the RequestContext that selects the
  // user's private file folder, cfo.ai connection and Neatlogs trace scope (also on approval
  // resumes, so an approved delete or cfo.ai change runs as this user). With
  // an approval message (last role "assistant"), handleChatStream resumes each approved/denied
  // tool call by its run id instead.
  // The span covers stream creation and the whole response write, so it ends only once the run
  // has finished (or the client disconnected). The thread id is the Neatlogs session, so one
  // conversation with an agent groups as a single session.
  const threadId = chatThreadId(user.id, agentId);
  await traceRequest("web", threadId, async () => {
    const requestContext = new RequestContext([
      [WORKSPACE_USER_KEY, user.id],
      [USER_ROLE_KEY, user.role],
    ]);
    const stream = await handleChatStream({
      mastra,
      agentId,
      version: "v7",
      params: {
        messages: [message],
        memory: { thread: threadId, resource: user.id },
        requestContext,
        abortSignal: abort.signal,
      },
      onError: (error) => {
        console.error("Web chat stream failed", { agentId, error });
        return "Sorry, something went wrong while generating a reply.";
      },
    });
    const response = createUIMessageStreamResponse({ stream });

    res.writeHead(response.status, Object.fromEntries(response.headers));
    res.flushHeaders();
    if (!response.body) {
      res.end();
      return;
    }
    try {
      for await (const chunk of response.body) {
        if (abort.signal.aborted) break;
        res.write(chunk);
      }
    } finally {
      res.end();
    }
  }, { agentId, role: last.role }, { userId: user.id, threadId, agentId, tags: last.role === "assistant" ? ["approval-resume"] : [] });
}

/** GET/DELETE /api/chat/:agentId/history — read or clear the caller's own chat with one agent. */
export async function handleChatHistory(
  agentKeyOrId: string,
  req: http.IncomingMessage,
  res: http.ServerResponse,
  user: SessionUser,
): Promise<void> {
  if (req.method !== "GET" && req.method !== "DELETE") {
    res.writeHead(405, { allow: "GET, DELETE" }).end();
    return;
  }
  const agentId = resolveAgentId(agentKeyOrId);
  if (!agentId) {
    sendJson(res, 404, { error: `Unknown agent: ${agentKeyOrId}` });
    return;
  }
  if (!canUseAgent(user, agentId)) {
    sendJson(res, 403, { error: "Forbidden" });
    return;
  }

  const thread = await ownThread(agentId, user);
  if (req.method === "DELETE") {
    if (thread) await thread.memory.deleteThread(thread.ids.threadId);
    res.writeHead(204).end();
    return;
  }
  if (!thread) {
    sendJson(res, 200, { messages: [] });
    return;
  }
  const { messages } = await thread.memory.recall({ ...thread.ids, perPage: false });
  sendJson(res, 200, { messages: toAISdkMessages(messages, { version: "v7" }) });
}

/**
 * The caller's own saved chat with an agent, or undefined when there is none. The thread id embeds
 * the user id and the resource id is checked, so only the caller's own chat is reachable.
 */
async function ownThread(agentId: string, user: SessionUser) {
  const agent = Object.values(mastra.listAgents()).find((a) => a.id === agentId);
  const memory = await agent?.getMemory();
  const threadId = chatThreadId(user.id, agentId);
  const thread = memory ? await memory.getThreadById({ threadId }) : null;
  if (!memory || thread?.resourceId !== user.id) return undefined;
  return { memory, ids: { threadId, resourceId: user.id } };
}

/**
 * A new user message moves past any approval still awaiting a decision: it is cleared from the
 * stored history (so it is no longer offered, and a late decision gets 409) and its suspended run
 * is discarded, deleting the same snapshot rows Mastra deletes when an agent run finishes. For an
 * approval raised by a delegated sub-agent, the sub-agent's own suspended run is discarded too.
 */
async function dropPendingApprovals(agentId: string, user: SessionUser): Promise<void> {
  const thread = await ownThread(agentId, user);
  if (!thread) return;
  const { messages } = await thread.memory.recall({ ...thread.ids, perPage: false });
  const dropped = withoutPendingApprovals(messages);
  if (dropped.messages.length === 0) return;
  const storage = mastra.getStorage();
  await (await storage?.getStore("memory"))?.updateMessages({ messages: dropped.messages });
  const workflows = await storage?.getStore("workflows");
  for (const runId of dropped.runIds) {
    await workflows?.deleteWorkflowRunById({ runId, workflowName: "agentic-loop" });
    await workflows?.deleteWorkflowRunById({ runId, workflowName: "executionWorkflow" });
  }
}

export function sendJson(res: http.ServerResponse, status: number, body: unknown): void {
  res.writeHead(status, { "content-type": "application/json; charset=utf-8" });
  res.end(JSON.stringify(body));
}

class BodyTooLargeError extends Error {}

async function readBody(req: http.IncomingMessage): Promise<string> {
  const chunks: Buffer[] = [];
  let size = 0;
  for await (const chunk of req) {
    size += (chunk as Buffer).length;
    if (size > MAX_BODY_BYTES) throw new BodyTooLargeError();
    chunks.push(chunk as Buffer);
  }
  return Buffer.concat(chunks).toString("utf8");
}

import { init, log, trace } from "neatlogs";
import { recordTraceOwners } from "./neatlogs/trace-owners";

export const telemetryReady = init({
  workflowName: "nlhack",
  apiKey: process.env.NEATLOGS_API_KEY,
  captureLogs: true,
  debug: process.env.NEATLOGS_DEBUG === "true",
  ...(process.env.NEATLOGS_ENDPOINT ? { endpoint: process.env.NEATLOGS_ENDPOINT } : {}),
});

if (!process.env.NEATLOGS_API_KEY) {
  console.warn("NEATLOGS_API_KEY is missing: traces will not be exported to the dashboard.");
}

const DEPARTMENT_TAGS: Record<string, string> = {
  cfo: "dept:finance",
  legal: "dept:legal",
  hr: "dept:hr",
  marketing: "dept:marketing",
  sales: "dept:sales",
  "customer-success": "dept:customer-success",
  "market-researcher": "dept:research",
  github: "dept:engineering",
  neatlogs: "dept:observability",
  assistant: "dept:general",
};

export type TraceContext = {
  userId?: string;
  /** For web, doubles as the Neatlogs session id so a whole conversation groups as one session. */
  threadId?: string;
  agentId?: string;
  tags?: string[];
};

export async function traceRequest<T>(
  channel: "cli" | "web",
  sessionId: string,
  run: () => Promise<T>,
  input?: unknown,
  context: TraceContext = {},
): Promise<T> {
  await telemetryReady;
  const { userId, threadId, agentId } = context;
  const department = agentId ? DEPARTMENT_TAGS[agentId] : undefined;
  const tags = [...(context.tags ?? []), ...(department ? [department] : [])];
  return trace({
    name: `${channel}.request`,
    kind: "WORKFLOW",
    sessionId: channel === "web" && threadId ? threadId : sessionId,
    sessionEntryPoint: channel,
    endUserId: userId,
    input,
    tags,
    // OpenTelemetry attributes must be primitives, so metadata is serialized.
    metadata: JSON.stringify({ agentId, threadId, channel }),
    attributes: {
      "app.channel": channel,
      ...(agentId ? { "app.agent_id": agentId } : {}),
      ...(threadId ? { "app.thread_id": threadId } : {}),
    },
  }, async (activeSpan) => {
    const traceId = activeSpan.spanContext().traceId;
    console.info("Neatlogs trace started", { channel, traceId, sessionId, agentId });
    // Web traces belong to the signed-in user; the Neat Bot shows non-admins only their own.
    if (channel === "web" && userId) {
      try {
        recordTraceOwners(userId, [traceId]);
      } catch (error) {
        console.warn("[neatlogs] could not record trace owner:", error instanceof Error ? error.message : error);
      }
    }
    log("Request started", { channel });
    try {
      const result = await run();
      log("Request completed", { channel });
      return result;
    } catch (error) {
      log("Request failed", { channel, level: "error", error: error instanceof Error ? error.message : String(error) });
      throw error;
    }
  });
}
import http from "node:http";
import { toNodeHandler } from "better-auth/node";
import { auth } from "./auth";
import { requireUser } from "./auth/session";
import { cfoConfigError } from "./cfo/oauth";
import { handleCfoCallback, handleCfoConnect, handleCfoDisconnect, handleCfoStatus } from "./cfo/routes";
import { cfoDb } from "./cfo/store";
import { handleChat, handleChatHistory, listAgents, sendJson } from "./chat-api";
import { createWebHandler } from "./web";

const authHandler = toNodeHandler(auth);

// cfo.ai per-user OAuth: create tables now; routes answer 503 until configured.
cfoDb();
const cfoConfigIssue = cfoConfigError();
if (cfoConfigIssue) console.warn(`cfo.ai connection disabled: ${cfoConfigIssue}. See README "cfo.ai connection".`);

const server = http.createServer(async (req, res) => {
  const url = new URL(req.url ?? "/", `http://${req.headers.host ?? "localhost"}`);

  if (req.method === "GET" && url.pathname === "/health") {
    res.writeHead(200, { "content-type": "application/json" });
    res.end(JSON.stringify({ status: "ok" }));
    return;
  }

  // Better Auth endpoints (sign-in, sign-out, session)
  if (url.pathname === "/api/auth" || url.pathname.startsWith("/api/auth/")) {
    try {
      await authHandler(req, res);
    } catch (error: unknown) {
      console.error("Auth request failed", error);
      if (!res.headersSent) sendJson(res, 500, { error: "Auth failed" });
      else res.end();
    }
    return;
  }

  // Current user
  if (url.pathname === "/api/me") {
    if (req.method !== "GET") {
      res.writeHead(405, { allow: "GET" }).end();
      return;
    }
    const user = await requireUser(req, res);
    if (!user) return;
    sendJson(res, 200, { user });
    return;
  }

  // Web chat API
  if (url.pathname === "/api/agents") {
    if (req.method !== "GET") {
      res.writeHead(405, { allow: "GET" }).end();
      return;
    }
    const user = await requireUser(req, res);
    if (!user) return;
    sendJson(res, 200, listAgents(user));
    return;
  }

  const historyMatch = url.pathname.match(/^\/api\/chat\/([^/]+)\/history$/);
  if (historyMatch) {
    try {
      const user = await requireUser(req, res);
      if (!user) return;
      await handleChatHistory(decodeURIComponent(historyMatch[1]), req, res, user);
    } catch (error: unknown) {
      console.error("Chat history failed", error);
      if (!res.headersSent) sendJson(res, 500, { error: "Chat history failed" });
      else res.end();
    }
    return;
  }

  const chatMatch = url.pathname.match(/^\/api\/chat\/([^/]+)$/);
  if (chatMatch) {
    try {
      const user = await requireUser(req, res);
      if (!user) return;
      await handleChat(decodeURIComponent(chatMatch[1]), req, res, user);
    } catch (error: unknown) {
      console.error("Web chat failed", error);
      if (!res.headersSent) sendJson(res, 500, { error: "Chat failed" });
      else res.end();
    }
    return;
  }

  // cfo.ai OAuth connection (per signed-in user)
  if (url.pathname.startsWith("/api/cfo/")) {
    const route = url.pathname.slice("/api/cfo/".length);
    const allowed: Record<string, string[]> = {
      connect: ["GET"],
      callback: ["GET"],
      status: ["GET"],
      disconnect: ["POST", "DELETE"],
    };
    const methods = allowed[route];
    if (!methods) {
      res.writeHead(404).end();
      return;
    }
    if (!methods.includes(req.method ?? "")) {
      res.writeHead(405, { allow: methods.join(", ") }).end();
      return;
    }
    try {
      const user = await requireUser(req, res);
      if (!user) return;
      if (route === "connect") await handleCfoConnect(res, user);
      else if (route === "callback") await handleCfoCallback(url, res, user);
      else if (route === "status") handleCfoStatus(res, user);
      else handleCfoDisconnect(res, user);
    } catch (error: unknown) {
      console.error("cfo.ai route failed", (error as Error).message);
      if (!res.headersSent) sendJson(res, 500, { error: "cfo.ai request failed" });
      else res.end();
    }
    return;
  }

  if (url.pathname === "/api" || url.pathname.startsWith("/api/")) {
    res.writeHead(404).end();
    return;
  }

  // Everything else is the web UI (Vite dev middleware, or web/dist in production).
  webHandler(req, res);
});

const webHandler = await createWebHandler(server);

const PORT = Number(process.env.PORT) || 3000;
server.listen(PORT, () => {
  console.log(`Server listening on port ${PORT}`);
});
import { mkdirSync } from "node:fs";
import { join } from "node:path";
import type { RequestContext } from "@mastra/core/request-context";
import { LocalFilesystem, WORKSPACE_TOOLS, Workspace } from "@mastra/core/workspace";
import { dataDir } from "../data-dir";

/**
 * RequestContext key holding the signed-in user's id. Only the server sets it (src/chat-api.ts),
 * never from client input. Delegated sub-agents receive a copy of the caller's RequestContext, so
 * they resolve the same folder.
 */
export const WORKSPACE_USER_KEY = "nlhack.workspaceUserId";

/**
 * RequestContext key holding the signed-in user's role ("admin" | "employee"). Set only by the
 * server (src/chat-api.ts) next to WORKSPACE_USER_KEY, never from client input; absent for the CLI.
 */
export const USER_ROLE_KEY = "nlhack.userRole";

/** Folder used when no user is in the RequestContext: the CLI (`npm start`) and `mastra dev`. */
const LOCAL_FOLDER = "local";

const SAFE_USER_ID = /^[A-Za-z0-9_-]{1,128}$/;

/**
 * The user's own folder, DATA_DIR/files/<userId>. The id must be a plain folder name; anything
 * else is refused rather than mapped onto a shared or parent folder.
 */
export function userFilesDir(userId: string): string {
  if (!SAFE_USER_ID.test(userId)) throw new Error("Refusing file workspace: user id is not a safe folder name");
  return join(dataDir(), "files", userId);
}

function folderFor(requestContext: RequestContext | undefined): string {
  const value = typeof requestContext?.get === "function" ? requestContext.get(WORKSPACE_USER_KEY) : undefined;
  if (value === undefined || value === null) return userFilesDir(LOCAL_FOLDER);
  if (typeof value !== "string") throw new Error("Refusing file workspace: user id is not a string");
  return userFilesDir(value);
}

const FS = WORKSPACE_TOOLS.FILESYSTEM;

/**
 * One private file folder per user, shared by every agent. Files persist on disk across chats and
 * restarts. Only deleting needs the user's approval; editing in place (edit_file, ast_edit) is off,
 * and no sandbox or search index is configured, so no command or index tools exist.
 */
export const workspace = new Workspace({
  id: "user-files",
  name: "User files",
  filesystem: ({ requestContext }) => {
    const basePath = folderFor(requestContext);
    mkdirSync(basePath, { recursive: true });
    return new LocalFilesystem({
      basePath,
      contained: true,
      // Replaces the default text, which would put the absolute disk path in the prompt.
      instructions:
        "This is the current user's private file workspace. Use relative paths such as \"notes/plan.md\" (the root is \".\"); absolute paths and paths outside it are refused.",
    });
  },
  tools: {
    // Off by default, so only the tools listed as enabled below are ever exposed.
    enabled: false,
    requireApproval: false,
    [FS.READ_FILE]: { enabled: true },
    [FS.WRITE_FILE]: { enabled: true },
    [FS.LIST_FILES]: { enabled: true },
    [FS.GREP]: { enabled: true },
    [FS.FILE_STAT]: { enabled: true },
    [FS.MKDIR]: { enabled: true },
    [FS.DELETE]: { enabled: true, requireApproval: true },
    [FS.EDIT_FILE]: { enabled: false },
    [FS.AST_EDIT]: { enabled: false },
  },
});
import { Agent } from "@mastra/core/agent";
import { memory } from "../memory";
import { wrapMastra } from "neatlogs/mastra";
import { ASSISTANT_INSTRUCTIONS } from "../prompts";
import { marketResearcher } from "./market-researcher";
import { cfoAgent } from "./cfo";
import { githubAgent } from "./github";
import { neatlogsAgent } from "./neatlogs";
import { customerSuccessAgent } from "./customer-success";
import { legalAgent } from "./legal";
import { hrAgent } from "./hr";
import { marketingAgent } from "./marketing";
import { salesAgent } from "./sales";

export const assistant = wrapMastra(new Agent({
  id: "assistant",
  name: "Primary Bot",
