// Temporary verification for per-turn usage caps. Run from the repo root with tsx.
import { mkdtempSync } from "node:fs";
import http from "node:http";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { execFileSync } from "node:child_process";

const REPO = "/Users/apple/Open/nlhack";
const dataDir = process.env.CAPS_TEST_DATA_DIR ?? mkdtempSync(join(tmpdir(), "caps-test-"));
process.env.DATA_DIR = dataDir;
delete process.env.NEATLOGS_API_KEY;

const { MockLanguageModelV3 } = await import(`${REPO}/node_modules/ai/dist/test/index.js`);
const { mastra } = await import(`${REPO}/src/mastra/index.ts`);
const { handleChat, handleChatHistory } = await import(`${REPO}/src/chat-api.ts`);
const { handleAgentCaps } = await import(`${REPO}/src/usage/routes.ts`);

type Step = { text?: string; tool?: { name: string; input: unknown }; input: number; output: number };
const scripts: Record<string, Step[]> = {};
const calls: Record<string, number> = {};

function mockFor(agentId: string) {
  return new MockLanguageModelV3({
    provider: "deepseek",
    modelId: "deepseek-flash",
    doStream: async () => {
      calls[agentId] = (calls[agentId] ?? 0) + 1;
      const step = scripts[agentId]?.shift();
      if (!step) throw new Error(`no scripted step left for ${agentId}`);
      const parts: unknown[] = [{ type: "stream-start", warnings: [] }];
      if (step.text) {
        parts.push({ type: "text-start", id: "t" }, { type: "text-delta", id: "t", delta: step.text }, { type: "text-end", id: "t" });
      }
      if (step.tool) {
        parts.push({ type: "tool-call", toolCallId: `call-${agentId}-${calls[agentId]}`, toolName: step.tool.name, input: JSON.stringify(step.tool.input) });
      }
      parts.push({
        type: "finish",
        finishReason: { unified: step.tool ? "tool-calls" : "stop", raw: undefined },
        usage: {
          inputTokens: { total: step.input, noCache: step.input, cacheRead: 0, cacheWrite: 0 },
          outputTokens: { total: step.output, text: step.output, reasoning: 0 },
        },
      });
      return { stream: new ReadableStream({ start(c) { for (const p of parts) c.enqueue(p); c.close(); } }) };
    },
  });
}

for (const agent of Object.values(mastra.listAgents()) as any[]) agent.__updateModel({ model: mockFor(agent.id) });

const users: Record<string, any> = {
  alice: { id: "alice", name: "Alice", username: "alice", role: "employee" },
  bob: { id: "bob", name: "Bob", username: "bob", role: "employee" },
};

const server = http.createServer(async (req, res) => {
  const url = new URL(req.url!, "http://x");
  const user = users[String(req.headers["x-user"] ?? "alice")];
  let m;
  try {
    if ((m = url.pathname.match(/^\/chat\/([^/]+)$/))) return await handleChat(m[1], req, res, user);
    if ((m = url.pathname.match(/^\/history\/([^/]+)$/))) return await handleChatHistory(m[1], req, res, user);
    if ((m = url.pathname.match(/^\/caps\/([^/]+)$/))) return await handleAgentCaps(m[1], req, res, user);
  } catch (e) {
    console.error("server error", e);
    if (!res.headersSent) res.writeHead(500);
    res.end();
    return;
  }
  res.writeHead(404).end();
});
await new Promise<void>((r) => server.listen(0, r));
const base = `http://127.0.0.1:${(server.address() as any).port}`;

let failures = 0;
function check(name: string, ok: boolean, detail?: unknown) {
  console.log(`${ok ? "PASS" : "FAIL"} ${name}${ok ? "" : ` -> ${JSON.stringify(detail)}`}`);
  if (!ok) failures++;
}

async function chat(agent: string, text: string, user = "alice") {
  const res = await fetch(`${base}/chat/${agent}`, {
    method: "POST",
    headers: { "content-type": "application/json", "x-user": user },
    body: JSON.stringify({ messages: [{ id: `m-${Math.random()}`, role: "user", parts: [{ type: "text", text }] }] }),
  });
  const body = await res.text();
  const parts = body.split("\n").filter((l) => l.startsWith("data: ") && l !== "data: [DONE]").map((l) => JSON.parse(l.slice(6)));
  return { status: res.status, parts };
}
const usageParts = (parts: any[]) => parts.filter((p) => p.type === "data-turn-usage").map((p) => p.data);
const textOf = (parts: any[]) => parts.filter((p) => p.type === "text-delta").map((p) => p.delta).join("");
async function caps(agent: string, method = "GET", body?: unknown, user = "alice") {
  const res = await fetch(`${base}/caps/${agent}`, { method, headers: { "x-user": user, "content-type": "application/json" }, body: body === undefined ? undefined : typeof body === "string" ? body : JSON.stringify(body) });
  return { status: res.status, json: await res.json().catch(() => null) };
}
const cost = (i: number, o: number) => (i * 0.3 + o * 1.2) / 1e6;
const near = (a: number, b: number) => Math.abs(a - b) < 1e-6;

// (1) Usage parts streamed per step with correct sums (HR Bot, tool step + text step).
scripts.hr = [
  { text: "Checking files. ", tool: { name: "mastra_workspace_list_files", input: { path: "." } }, input: 1000, output: 100 },
  { text: "All done.", input: 1200, output: 50 },
];
{
  const { status, parts } = await chat("hr", "list my files");
  const u = usageParts(parts);
  const final = u.at(-1);
